def check_k(k, max_elements=95):
    # For a given k, we want to find a semigroup R with |R| >= max_elements
    # that minimizes sum(R).
    # The smallest such R will likely be a "multiple-like" semigroup.
    # Let's try R = {k, 2k, 3k, ..., mk}
    m = 191 // k
    if m >= max_elements:
        R = [i for i in range(k, 192, k)]
        return sum(R), sum(range(1, 192)) - sum(R)
    else:
        # We need to add more elements.
        # To minimize sum(R), we want to add the smallest possible elements.
        # But R must be a semigroup.
        # This is complex, but we can estimate.
        # If we add x, we must add x+k, x+2k, ...
        # The smallest x would be k+1, k+2, ...
        # But if we add k+1, we also add (k+1)+k, (k+1)+2k, ...
        # So R would contain almost all numbers >= k+1.
        # R = {k, k+1, k+2, ..., 191}
        # Number of elements: 191 - k + 1
        if 191 - k + 1 >= max_elements:
            R = list(range(k, 192))
            return sum(R), sum(range(1, 192)) - sum(R)
        else:
            return None, None

for k in range(1, 192):
    res_sum_R, res_sum_M = check_k(k, 95)
    if res_sum_R is not None:
        print(f"k={k}, sum_R={res_sum_R}, sum_M={res_sum_M}")
